 76	                                  size_t *total_bytes, bool *limit)
 77	{
 78	    if (source == NULL || evaluated == NULL || total_bytes == NULL ||
 79	        limit == NULL || source->clips == NULL || evaluated->clips != source->clips)
 80	        return false;
 81	    *limit = false;
 82	    size_t capacity = 0U, pointer_bytes = 0U, table_bytes = 0U;
 83	    if (!hash_capacity(source->shape_count, &capacity) ||
 84	        !checked_bytes(source->shape_count, sizeof(*evaluated->clips),
 85	                       &pointer_bytes) ||
 86	        !checked_bytes(capacity, sizeof(clip_copy_entry), &table_bytes)) {
 87	        *limit = true;
 88	        return false;
 89	    }
 90	    if (pointer_bytes > SIZE_MAX - table_bytes ||
 91	        !reserve_clone_bytes(pointer_bytes + table_bytes, total_bytes, limit))
 92	        return false;
 93	    svg_shape_clip **copies = source->shape_count == 0U ? NULL :
 94	        calloc(source->shape_count, sizeof(*copies));
 95	    clip_copy_entry *entries = calloc(capacity, sizeof(*entries));
 96	    if ((source->shape_count != 0U && copies == NULL) || entries == NULL) {
 97	        free(copies);
 98	        free(entries);
 99	        *total_bytes -= pointer_bytes + table_bytes;
100	        return false;
101	    }
102	    evaluated->clips = copies;
103	    size_t mask = capacity - 1U;
104	    bool ok = true;
105	    for (size_t shape = 0U; shape < source->shape_count; ++shape) {
106	        const svg_shape_clip *root = source->clips[shape];
107	        if (root == NULL) continue;
