158	static bool node_product(const svg_shape_document *document, size_t node_index,
159	                         geom_affine *full, geom_affine *before_suffix,
160	                         size_t *work, size_t work_limit)
161	{
162	    size_t chain[ANIMATION_CLIP_CHAIN_MAX];
163	    size_t count = 0U;
164	    size_t current = node_index;
165	    while (current != SVG_SHAPE_NO_TRANSFORM_NODE) {
166	        if (current >= document->transform_node_count ||
167	            count >= ANIMATION_CLIP_CHAIN_MAX ||
168	            !add_work(1U, work, work_limit)) return false;
169	        chain[count++] = current;
170	        current = document->transform_nodes[current].parent;
171	    }
172	    geom_affine result = geom_affine_identity();
173	    geom_affine partial = geom_affine_identity();
174	    while (count != 0U) {
175	        size_t index = chain[--count];
176	        const svg_shape_transform_frame *node = &document->transform_nodes[index];
177	        geom_affine local;
178	        if (!geom_affine_compose(node->motion, node->attribute, &local))
179	            return false;
180	        if (index == node_index) {
181	            if (!geom_affine_compose(result, local, &partial)) return false;
182	        }
183	        if (!geom_affine_compose(local, node->suffix, &local) ||
184	            !geom_affine_compose(result, local, &result)) return false;
185	    }
