251	/// Evaluate parsed overlays into a borrowed scene frame with owned changed tables.
252	pub fn evaluate_frame<'a>(
253	    view: SceneView<'a>,
254	    time_seconds: f64,
255	    control: &mut dyn WorkControl,
256	) -> Result<EvaluatedFrame<'a>> {
257	    let overlay =
258	        evaluate_view_controlled(view.animation(), time_seconds, control).map_err(|e| match e {
259	            EvaluationError::InvalidTime => invalid(0),
260	            EvaluationError::InvalidTrack => diag(ErrorKind::Unsupported, 0),
261	            EvaluationError::OutOfMemory => oom(),
262	            EvaluationError::Canceled => diag(ErrorKind::Canceled, 0),
263	            EvaluationError::Limit => limit(LimitKind::Work),
264	            EvaluationError::Overflow => arithmetic(),
265	        })?;
266	    let mut builder = FrameBuilder::new(view, usize::MAX)?;
267	    if !overlay.items.iter().any(|item| item.active) {
268	        return builder.finish(control);
269	    }
270	    let mut work = 0usize;
271	    let mut transforms = copy_table(view.transforms, control)?;
272	    let mut transform_seen = Vec::new();
273	    transform_seen
274	        .try_reserve_exact(view.transforms.len())
275	        .map_err(|_| oom())?;
276	    transform_seen.resize(view.transforms.len(), false);
277	    let mut world = Vec::new();
278	    world
279	        .try_reserve_exact(view.shapes.len())
280	        .map_err(|_| oom())?;
281	    for shape in view.shapes {
282	        world.push(product(view.transforms, shape, control, &mut work)?);
283	    }
284	    let mut edges = copy_table(view.edges, control)?;
285	    let mut colors = copy_table(view.edge_colors, control)?;
286	    let mut shapes = copy_table(view.shapes, control)?;
287	    let mut fills = copy_table(view.fill_paints, control)?;
288	    let mut strokes = copy_table(view.stroke_paints, control)?;
289	    let mut changed_edges = false;
290	    let mut changed_colors = false;
291	    let mut changed_shapes = false;
292	    let mut changed_fills = false;
293	    let mut changed_strokes = false;
294	    let has_clip_updates = !view.clips.is_empty()
295	        && overlay.items.iter().any(|item| {
296	            item.active
297	                && view
298	                    .animation()
299	                    .tracks
300	                    .get(item.track_index)
301	                    .is_some_and(|track| changes_clips(track, *item))
302	        });
303	    let mut clip_shape_flags = Vec::new();
304	    let mut clips = if !has_clip_updates {
305	        None
306	    } else {
307	        Some(clips::clone_clips_for_overlay(view, control)?)
308	    };
309	    if has_clip_updates {
310	        clip_shape_flags
311	            .try_reserve_exact(view.shapes.len())
312	            .map_err(|_| oom())?;
313	        clip_shape_flags.resize(view.shapes.len(), false);
314	    }
315	    for item in &overlay.items {
316	        if !item.active {
317	            continue;
318	        }
319	        charge(control, 1)?;
320	        work = work.checked_add(1).ok_or_else(arithmetic)?;
321	        if work > WORK_MAX {
322	            return Err(limit(LimitKind::Work));
323	        }
324	        let track = view
325	            .animation()
326	            .tracks
327	            .get(item.track_index)
328	            .ok_or_else(|| invalid(0))?;
329	        match track.kind {
330	            Kind::Transform | Kind::Motion => {
331	                let anim = if track.kind == Kind::Transform {
332	                    transform_value(track, item.value)
333	                        .ok_or_else(|| diag(ErrorKind::Unsupported, track.element.offset))?
334	                } else if item.value.kind == ValueKind::Motion {
335	                    let (s, c) = (item.value.number[2] * 0.017453292519943295769).sin_cos();
336	                    Affine {
337	                        a: c,
338	                        b: s,
339	                        c: -s,
340	                        d: c,
341	                        e: item.value.number[0],
342	                        f: item.value.number[1],
343	                    }
344	                } else {
345	                    return Err(diag(ErrorKind::Unsupported, track.element.offset));
346	                };
347	                let mut found = false;
348	                for (i, node) in transforms.iter_mut().enumerate() {
349	                    charge(control, 1)?;
350	                    count_work(&mut work, 1)?;
351	                    if node.source_offset != track.target.offset {
352	                        continue;
353	                    }
354	                    found = true;
355	                    if track.kind == Kind::Motion {
356	                        node.motion = affine_compose(node.motion, anim)
357	                            .ok_or_else(|| invalid(track.element.offset))?;
358	                    } else if track.additive_sum || transform_seen[i] {
359	                        node.attribute = affine_compose(node.attribute, anim)
360	                            .ok_or_else(|| invalid(track.element.offset))?;
361	                    } else {
362	                        node.attribute = anim;
363	                    }
364	                    transform_seen[i] = true;
365	                }
366	                if found {
367	                    for si in 0..shapes.len() {
368	                        let shape = shapes[si];
369	                        charge(control, 1)?;
370	                        count_work(&mut work, 1)?;
371	                        let mut n = shape.source.transform_node;
372	                        let mut has = false;
373	                        let mut depth = 0;
374	                        while let Some(id) = n {
375	                            if depth >= CHAIN_MAX || id.index() >= transforms.len() {
376	                                return Err(invalid(track.element.offset));
377	                            }
378	                            charge(control, 1)?;
379	                            count_work(&mut work, 1)?;
380	                            if transforms[id.index()].source_offset == track.target.offset {
381	                                has = true;
382	                                break;
383	                            }
384	                            n = transforms[id.index()].parent;
385	                            depth += 1;
386	                        }
387	                        if !has {
388	                            continue;
389	                        }
390	                        if has_effect(view, si, control, &mut work)? {
391	                            return Err(diag(ErrorKind::Unsupported, track.element.offset));
392	                        }
393	                        let next = product(&transforms, &shape, control, &mut work)?;
394	                        let delta = affine_compose(
395	                            next,
396	                            inverse(world[si], 1e-15)
397	                                .ok_or_else(|| invalid(track.element.offset))?,
398	                        )
399	                        .ok_or_else(|| invalid(track.element.offset))?;
400	                        map_shape_edges(view, &shape, delta, &mut edges, control, &mut work)?;
401	                        changed_edges = true;
402	                        world[si] = next;
403	                        let mut updated = shape;
404	                        updated.stroke_inverse = affine_compose(
405	                            updated.stroke_inverse,
406	                            inverse(delta, 1e-15).ok_or_else(|| invalid(track.element.offset))?,
407	                        )
408	                        .ok_or_else(|| invalid(track.element.offset))?;
409	                        if let Some(index) = updated.fill_paint {
410	                            if let Some(p) = fills.get_mut(index) {
411	                                if p.kind != PaintKind::Solid {
412	                                    p.user_inverse = affine_compose(
413	                                        p.user_inverse,
414	                                        inverse(delta, 1e-15).ok_or_else(|| invalid(0))?,
415	                                    )
416	                                    .ok_or_else(|| invalid(0))?;
417	                                    changed_fills = true;
418	                                }
419	                            }
420	                        }
421	                        if let Some(index) = updated.stroke_paint {
422	                            if let Some(p) = strokes.get_mut(index) {
423	                                if p.kind != PaintKind::Solid {
424	                                    p.user_inverse = affine_compose(
425	                                        p.user_inverse,
426	                                        inverse(delta, 1e-15).ok_or_else(|| invalid(0))?,
427	                                    )
428	                                    .ok_or_else(|| invalid(0))?;
429	                                    changed_strokes = true;
430	                                }
431	                            }
432	                        }
433	                        shapes[si] = updated;
434	                        changed_shapes = true;
435	                        if !clip_shape_flags.is_empty() {
436	                            clip_shape_flags[si] = true;
437	                        }
438	                    }
439	                }
440	            }
441	            _ => apply_value(
442	                view,
443	                track,
444	                *item,
445	                &mut edges,
446	                &mut colors,
447	                &mut shapes,
448	                &mut fills,
449	                &mut strokes,
450	                &world,
451	                control,
452	                &mut work,
453	                &mut changed_edges,
454	                &mut changed_colors,
455	                &mut changed_shapes,
456	                &mut changed_fills,
457	                &mut changed_strokes,
458	                &mut clip_shape_flags,
459	            )?,
460	        }
461	        if let Some(clip_table) = clips.as_mut() {
462	            for si in 0..clip_shape_flags.len() {
463	                if clip_shape_flags[si] {
464	                    clips::update_clip_table_for_shape(
465	                        &transforms,
466	                        &shapes,
467	                        &edges,
468	                        clip_table,
469	                        si,
470	                        true,
471	                        control,
472	                        &mut work,
473	                    )?;
474	                    clip_shape_flags[si] = false;
475	                }
476	            }
477	        }
478	    }
479	    if changed_edges {
