 18	const CHAIN_MAX: usize = 128;
 19	const WORK_MAX: usize = 50_000_000;
 20	
 21	fn diag(kind: ErrorKind, offset: usize) -> Diagnostic {
 22	    Diagnostic { kind, offset }
 23	}
 24	fn invalid(offset: usize) -> Diagnostic {
 25	    diag(ErrorKind::InvalidArgument, offset)
 26	}
 27	fn limit(kind: LimitKind) -> Diagnostic {
 28	    diag(ErrorKind::Limit(kind), 0)
 29	}
 30	fn arithmetic() -> Diagnostic {
 31	    limit(LimitKind::Arithmetic)
 32	}
 33	fn oom() -> Diagnostic {
 34	    diag(ErrorKind::OutOfMemory, 0)
 35	}
 36	fn charge(control: &mut dyn WorkControl, amount: usize) -> Result<()> {
 37	    let units = u64::try_from(amount).map_err(|_| arithmetic())?;
 38	    control
 39	        .charge(WorkKind::AnimationTransform, units)
 40	        .map_err(|s| match s {
 41	            vexel_scene::Stop::Canceled => diag(ErrorKind::Canceled, 0),
 42	            vexel_scene::Stop::Limit => limit(LimitKind::Work),
 43	            vexel_scene::Stop::Overflow => arithmetic(),
 44	        })
 45	}
 46	fn count_work(work: &mut usize, amount: usize) -> Result<()> {
 47	    *work = work.checked_add(amount).ok_or_else(arithmetic)?;
 48	    if *work > WORK_MAX {
 49	        return Err(limit(LimitKind::Work));
 50	    }
 51	    Ok(())
 52	}
 53	fn changes_clips(track: &Track, item: OverlayItem) -> bool {
 54	    matches!(track.kind, Kind::Transform | Kind::Motion)
 55	        || (matches!(track.kind, Kind::Animate | Kind::Set)
 56	            && item.value.kind == ValueKind::Number
 57	            && matches!(
 58	                track.attribute,
 59	                Attribute::X
 60	                    | Attribute::Y
 61	                    | Attribute::Cx
 62	                    | Attribute::Cy
 63	                    | Attribute::Width
 64	                    | Attribute::Height
 65	                    | Attribute::Rx
 66	                    | Attribute::Ry
 67	                    | Attribute::R
 68	            ))
 69	}
 70	fn copy_table<T: Copy>(values: &[T], control: &mut dyn WorkControl) -> Result<Vec<T>> {
 71	    let mut copy = Vec::new();
 72	    copy.try_reserve_exact(values.len()).map_err(|_| oom())?;
 73	    for value in values {
 74	        control
 75	            .charge(WorkKind::AnimationTransform, 1)
 76	            .map_err(|s| match s {
 77	                vexel_scene::Stop::Canceled => diag(ErrorKind::Canceled, 0),
 78	                vexel_scene::Stop::Limit => limit(LimitKind::Work),
 79	                vexel_scene::Stop::Overflow => arithmetic(),
 80	            })?;
 81	        copy.push(*value);
 82	    }
 83	    Ok(copy)
 84	}
