 86	fn inverse(m: Affine, threshold: f64) -> Option<Affine> {
 87	    let determinant = m.a * m.d - m.b * m.c;
 88	    if !determinant.is_finite() || determinant.abs() < threshold {
 89	        return None;
 90	    }
 91	    let k = 1.0 / determinant;
 92	    let out = Affine {
 93	        a: m.d * k,
 94	        b: -m.b * k,
 95	        c: -m.c * k,
 96	        d: m.a * k,
 97	        e: (m.c * m.f - m.d * m.e) * k,
 98	        f: (m.b * m.e - m.a * m.f) * k,
 99	    };
100	    vexel_geometry::affine_valid(out).then_some(out)
101	}
102	fn transform_value(track: &Track, value: Value) -> Option<Affine> {
103	    let x = value.number[0];
104	    let y = value.number[1];
105	    if !x.is_finite() || !y.is_finite() || x.abs() > 1e6 || y.abs() > 1e6 {
106	        return None;
107	    }
108	    let mut m = affine_identity();
109	    match track.transform_type {
110	        TransformType::Translate => {
111	            m.e = x;
112	            m.f = y;
113	        }
114	        TransformType::Scale => {
115	            m.a = x;
116	            m.d = if value.number[3] >= 2. { y } else { x };
117	        }
118	        TransformType::Rotate => {
119	            let angle = x * 0.017453292519943295769;
120	            let (s, c) = angle.sin_cos();
121	            if !s.is_finite() || !c.is_finite() {
122	                return None;
123	            }
124	            m = Affine {
125	                a: c,
126	                b: s,
127	                c: -s,
128	                d: c,
129	                e: 0.,
130	                f: 0.,
131	            };
132	            if value.number[3] >= 3. {
133	                let to = Affine {
134	                    e: value.number[1],
135	                    f: value.number[2],
136	                    ..affine_identity()
137	                };
138	                let from = Affine {
139	                    e: -value.number[1],
140	                    f: -value.number[2],
141	                    ..affine_identity()
142	                };
143	                m = affine_compose(affine_compose(to, m)?, from)?;
144	            }
145	        }
146	        TransformType::SkewX | TransformType::SkewY => {
147	            let t = (x * 0.017453292519943295769).tan();
148	            if !t.is_finite() || t.abs() > 1e6 {
149	                return None;
150	            }
151	            if track.transform_type == TransformType::SkewX {
152	                m.c = t
153	            } else {
154	                m.b = t
155	            }
156	        }
157	    }
158	    vexel_geometry::affine_valid(m).then_some(m)
159	}
160	fn product(
161	    transforms: &[TransformFrame],
162	    shape: &Shape,
163	    control: &mut dyn WorkControl,
164	    work: &mut usize,
165	) -> Result<Affine> {
166	    let mut chain = [None; CHAIN_MAX];
167	    let mut count = 0;
168	    let mut node = shape.source.transform_node;
169	    while let Some(id) = node {
170	        if count == CHAIN_MAX || id.index() >= transforms.len() {
171	            return Err(invalid(shape.source.element.start));
172	        }
173	        charge(control, 1)?;
174	        *work = work.checked_add(1).ok_or_else(arithmetic)?;
175	        if *work > WORK_MAX {
176	            return Err(limit(LimitKind::Work));
177	        }
178	        chain[count] = Some(id);
179	        count += 1;
180	        node = transforms[id.index()].parent;
181	    }
182	    let mut out = affine_identity();
183	    while count > 0 {
184	        count -= 1;
185	        let n = transforms[chain[count].ok_or_else(|| invalid(0))?.index()];
186	        let local = affine_compose(n.attribute, n.suffix)
187	            .and_then(|m| affine_compose(n.motion, m))
188	            .ok_or_else(|| invalid(n.source_offset))?;
189	        out = affine_compose(out, local).ok_or_else(|| invalid(n.source_offset))?;
190	    }
191	    Ok(out)
192	}
193	fn shape_bounds(
194	    shape: &Shape,
195	    current_edges: &[Edge],
196	    inverse: Affine,
197	    control: &mut dyn WorkControl,
198	    work: &mut usize,
199	) -> Result<[f64; 4]> {
200	    let edges = shape
201	        .edges
202	        .slice(current_edges)
203	        .ok_or_else(|| invalid(shape.source.element.start))?;
204	    if edges.is_empty() {
205	        return Err(invalid(shape.source.element.start));
206	    }
207	    charge(control, edges.len())?;
208	    *work = work.checked_add(edges.len()).ok_or_else(arithmetic)?;
209	    if *work > WORK_MAX {
210	        return Err(limit(LimitKind::Work));
211	    }
212	    let p = affine_map_point(inverse, edges[0].a).ok_or_else(|| invalid(0))?;
213	    let mut b = [p.x, p.y, p.x, p.y];
214	    for edge in edges {
215	        for point in [edge.a, edge.b] {
216	            let q = affine_map_point(inverse, point).ok_or_else(|| invalid(0))?;
217	            b[0] = b[0].min(q.x);
218	            b[1] = b[1].min(q.y);
219	            b[2] = b[2].max(q.x);
220	            b[3] = b[3].max(q.y);
221	        }
222	    }
223	    Ok(b)
224	}
225	fn map_shape_edges(
226	    view: SceneView<'_>,
227	    shape: &Shape,
228	    matrix: Affine,
229	    edges: &mut [Edge],
230	    control: &mut dyn WorkControl,
231	    work: &mut usize,
232	) -> Result<()> {
233	    let range = shape.edges;
234	    let end = range.end().ok_or_else(arithmetic)?;
235	    if end > edges.len() {
236	        return Err(invalid(shape.source.element.start));
237	    }
238	    charge(control, range.count)?;
239	    *work = work.checked_add(range.count).ok_or_else(arithmetic)?;
240	    if *work > WORK_MAX {

329	        match track.kind {
330	            Kind::Transform | Kind::Motion => {
331	                let anim = if track.kind == Kind::Transform {
332	                    transform_value(track, item.value)
333	                        .ok_or_else(|| diag(ErrorKind::Unsupported, track.element.offset))?
334	                } else if item.value.kind == ValueKind::Motion {
335	                    let (s, c) = (item.value.number[2] * 0.017453292519943295769).sin_cos();
336	                    Affine {
337	                        a: c,
338	                        b: s,
339	                        c: -s,
340	                        d: c,
341	                        e: item.value.number[0],
342	                        f: item.value.number[1],
343	                    }
344	                } else {
345	                    return Err(diag(ErrorKind::Unsupported, track.element.offset));
346	                };
347	                let mut found = false;
348	                for (i, node) in transforms.iter_mut().enumerate() {
349	                    charge(control, 1)?;
350	                    count_work(&mut work, 1)?;
351	                    if node.source_offset != track.target.offset {
352	                        continue;
353	                    }
354	                    found = true;
355	                    if track.kind == Kind::Motion {
356	                        node.motion = affine_compose(node.motion, anim)
357	                            .ok_or_else(|| invalid(track.element.offset))?;
358	                    } else if track.additive_sum || transform_seen[i] {
359	                        node.attribute = affine_compose(node.attribute, anim)
360	                            .ok_or_else(|| invalid(track.element.offset))?;
361	                    } else {
362	                        node.attribute = anim;
363	                    }
364	                    transform_seen[i] = true;
365	                }
366	                if found {
367	                    for si in 0..shapes.len() {
368	                        let shape = shapes[si];
369	                        charge(control, 1)?;
370	                        count_work(&mut work, 1)?;
371	                        let mut n = shape.source.transform_node;
372	                        let mut has = false;
373	                        let mut depth = 0;
374	                        while let Some(id) = n {
375	                            if depth >= CHAIN_MAX || id.index() >= transforms.len() {
376	                                return Err(invalid(track.element.offset));
377	                            }
378	                            charge(control, 1)?;
379	                            count_work(&mut work, 1)?;
380	                            if transforms[id.index()].source_offset == track.target.offset {
381	                                has = true;
382	                                break;
383	                            }
384	                            n = transforms[id.index()].parent;
385	                            depth += 1;
386	                        }
387	                        if !has {
388	                            continue;
389	                        }
390	                        if has_effect(view, si, control, &mut work)? {
391	                            return Err(diag(ErrorKind::Unsupported, track.element.offset));
392	                        }
393	                        let next = product(&transforms, &shape, control, &mut work)?;
394	                        let delta = affine_compose(
395	                            next,
396	                            inverse(world[si], 1e-15)
397	                                .ok_or_else(|| invalid(track.element.offset))?,
398	                        )
399	                        .ok_or_else(|| invalid(track.element.offset))?;
400	                        map_shape_edges(view, &shape, delta, &mut edges, control, &mut work)?;
401	                        changed_edges = true;
402	                        world[si] = next;
403	                        let mut updated = shape;
404	                        updated.stroke_inverse = affine_compose(
405	                            updated.stroke_inverse,
406	                            inverse(delta, 1e-15).ok_or_else(|| invalid(track.element.offset))?,
407	                        )
408	                        .ok_or_else(|| invalid(track.element.offset))?;
409	                        if let Some(index) = updated.fill_paint {
410	                            if let Some(p) = fills.get_mut(index) {
411	                                if p.kind != PaintKind::Solid {
412	                                    p.user_inverse = affine_compose(
413	                                        p.user_inverse,
414	                                        inverse(delta, 1e-15).ok_or_else(|| invalid(0))?,
415	                                    )
416	                                    .ok_or_else(|| invalid(0))?;
417	                                    changed_fills = true;
418	                                }
419	                            }
420	                        }
421	                        if let Some(index) = updated.stroke_paint {
422	                            if let Some(p) = strokes.get_mut(index) {
423	                                if p.kind != PaintKind::Solid {
424	                                    p.user_inverse = affine_compose(
425	                                        p.user_inverse,
426	                                        inverse(delta, 1e-15).ok_or_else(|| invalid(0))?,
427	                                    )
428	                                    .ok_or_else(|| invalid(0))?;
429	                                    changed_strokes = true;
430	                                }
431	                            }
432	                        }
433	                        shapes[si] = updated;
434	                        changed_shapes = true;
435	                        if !clip_shape_flags.is_empty() {
436	                            clip_shape_flags[si] = true;
437	                        }
438	                    }
439	                }
440	            }
441	            _ => apply_value(
442	                view,
443	                track,
444	                *item,
445	                &mut edges,
446	                &mut colors,
447	                &mut shapes,
448	                &mut fills,
449	                &mut strokes,
450	                &world,
451	                control,
452	                &mut work,
453	                &mut changed_edges,
454	                &mut changed_colors,
455	                &mut changed_shapes,
456	                &mut changed_fills,
457	                &mut changed_strokes,
458	                &mut clip_shape_flags,
459	            )?,
460	        }
461	        if let Some(clip_table) = clips.as_mut() {
462	            for si in 0..clip_shape_flags.len() {
463	                if clip_shape_flags[si] {
464	                    clips::update_clip_table_for_shape(
465	                        &transforms,
466	                        &shapes,
467	                        &edges,
468	                        clip_table,
469	                        si,
470	                        true,
471	                        control,
472	                        &mut work,
473	                    )?;
474	                    clip_shape_flags[si] = false;
475	                }
476	            }
477	        }
478	    }
479	    if changed_edges {
480	        builder.replace_edges(edges, control)?;
481	    }
482	    if changed_colors {
483	        builder.replace_colors(colors, control)?;
484	    }
485	    if changed_shapes {
486	        for (idx, value) in shapes.iter().enumerate() {
487	            let id = view.shape_id(idx).ok_or_else(|| invalid(0))?;
488	            if view.shapes.get(idx) != Some(value) {
489	                builder.set_shape(id, *value, control)?;
490	            }
491	        }
492	    }
493	    if changed_fills {
494	        for (i, p) in fills.into_iter().enumerate() {
495	            if view.fill_paints.get(i) != Some(&p) {
496	                builder.set_fill_paint(i, p, control)?;
497	            }
498	        }
499	    }
500	    if changed_strokes {
501	        for (i, p) in strokes.into_iter().enumerate() {
502	            if view.stroke_paints.get(i) != Some(&p) {
503	                builder.set_stroke_paint(i, p, control)?;
504	            }
505	        }
506	    }
507	    for (i, t) in transforms.into_iter().enumerate() {
508	        if view.transforms.get(i) != Some(&t) {
509	            let id = view.transform_id(i).ok_or_else(|| invalid(0))?;
510	            builder.set_transform(id, t, control)?;
511	        }
512	    }
513	    let mut frame = builder.finish(control)?;
514	    if let Some(clip_table) = clips {
515	        frame.replace_clips(clip_table, control)?;
516	    }
517	    Ok(frame)
518	}
