520	fn has_effect(
521	    view: SceneView<'_>,
522	    shape: usize,
523	    control: &mut dyn WorkControl,
524	    work: &mut usize,
525	) -> Result<bool> {
526	    for g in view.groups {
527	        charge(control, 1)?;
528	        *work = work.checked_add(1).ok_or_else(arithmetic)?;
529	        if *work > WORK_MAX {
530	            return Err(limit(LimitKind::Work));
531	        }
532	        if shape >= g.shapes.first
533	            && shape < g.shapes.end().ok_or_else(arithmetic)?
534	            && (g.filter.is_some() || g.mask.is_some())
535	        {
536	            return Ok(true);
537	        }
538	    }
539	    Ok(false)
540	}
