557	        let mut value = Value::default();
558	        value.number = [12.0, 3.0, 4.0, 3.0];
559	        let m = transform_value(&track(TransformType::Rotate), value).unwrap();
560	        assert!((m.a - 12f64.to_radians().cos()).abs() < 1e-12);
561	        assert!((m.b - 12f64.to_radians().sin()).abs() < 1e-12);
562	        assert!((m.e - (3.0 - m.a * 3.0 - m.c * 4.0)).abs() < 1e-12);
