  3	pub(super) fn apply_value(
  4	    view: SceneView<'_>,
  5	    t: &Track,
  6	    item: OverlayItem,
  7	    edges: &mut [Edge],
  8	    colors: &mut [[u8; 4]],
  9	    shapes: &mut [Shape],
 10	    fills: &mut [Paint],
 11	    _strokes: &mut [Paint],
 12	    world: &[Affine],
 13	    control: &mut dyn WorkControl,
 14	    work: &mut usize,
 15	    ce: &mut bool,
 16	    cc: &mut bool,
 17	    cs: &mut bool,
 18	    cf: &mut bool,
 19	    _csp: &mut bool,
 20	    clip_shape_flags: &mut [bool],
 21	) -> Result<()> {
 22	    let mut descendant = false;
 23	    let mut direct = false;
 24	    let target_end = t
 25	        .target
 26	        .offset
 27	        .checked_add(t.target.length)
 28	        .ok_or_else(arithmetic)?;
 29	    for (i, shape) in shapes.iter_mut().enumerate() {
 30	        charge(control, 1)?;
 31	        *work = work.checked_add(1).ok_or_else(arithmetic)?;
 32	        if *work > WORK_MAX {
 33	            return Err(limit(LimitKind::Work));
 34	        }
 35	        let mut node = shape.source.transform_node;
 36	        let mut depth = 0;
 37	        let mut in_target = shape.source.element.start >= t.target.offset
 38	            && shape.source.element.start < target_end;
 39	        while let Some(id) = node {
 40	            if depth >= CHAIN_MAX {
 41	                return Err(limit(LimitKind::Animation));
 42	            }
 43	            let n = view
 44	                .transform(id)
 45	                .ok_or_else(|| invalid(t.element.offset))?;
 46	            charge(control, 1)?;
 47	            count_work(work, 1)?;
 48	            if n.source_offset >= t.target.offset && n.source_offset < target_end {
 49	                in_target = true;
 50	            }
 51	            node = n.parent;
 52	            depth += 1;
 53	        }
 54	        if !in_target {
 55	            continue;
 56	        }
 57	        descendant = true;
 58	        let is_direct = shape.source.element.start == t.target.offset
 59	            || shape.source.transform_node.is_some_and(|id| {
 60	                view.transform(id)
 61	                    .is_some_and(|n| n.source_offset == t.target.offset)
 62	            });
 63	        if !is_direct {
 64	            continue;
 65	        }
 66	        direct = true;
 67	        match t.attribute {
 68	            Attribute::Fill if item.value.kind == ValueKind::Color => {
 69	                let r = shape.edges;
 70	                if r.end().is_none_or(|e| e > colors.len()) {
 71	                    return Err(invalid(t.element.offset));
 72	                }
 73	                charge(control, r.count)?;
 74	                for c in &mut colors[r.first..r.first + r.count] {
 75	                    *c = item.value.rgba;
 76	                }
 77	                *cc = true;
 78	            }
 79	            Attribute::Stroke if item.value.kind == ValueKind::Color => {
 80	                shape.stroke.rgba = item.value.rgba;
 81	                *cs = true;
 82	            }
 83	            Attribute::Opacity | Attribute::FillOpacity if item.value.kind == ValueKind::Number => {
 84	                let op = item.value.number[0].clamp(0., 1.);
 85	                let r = shape.edges;
 86	                if r.end().is_none_or(|e| e > colors.len()) {
 87	                    return Err(invalid(t.element.offset));
 88	                }
 89	                charge(control, r.count)?;
 90	                for c in &mut colors[r.first..r.first + r.count] {
 91	                    c[3] = (f64::from(c[3]) * op + 0.5).floor() as u8;
 92	                }
 93	                *cc = true;
 94	                if t.attribute == Attribute::Opacity {
 95	                    shape.stroke.rgba[3] =
 96	                        (f64::from(shape.stroke.rgba[3]) * op + 0.5).floor() as u8;
 97	                    *cs = true;
 98	                }
 99	            }
100	            Attribute::StrokeOpacity if item.value.kind == ValueKind::Number => {
101	                let op = item.value.number[0].clamp(0., 1.);
102	                shape.stroke.rgba[3] = (f64::from(shape.stroke.rgba[3]) * op + 0.5).floor() as u8;
103	                *cs = true;
104	            }
105	            Attribute::StrokeWidth | Attribute::StrokeDashoffset
106	                if item.value.kind == ValueKind::Number =>
107	            {
108	                let v = item.value.number[0];
109	                if v.abs() > 1e6 || (t.attribute == Attribute::StrokeWidth && v < 0.) {
110	                    return Err(diag(ErrorKind::Unsupported, t.element.offset));
111	                }
112	                if t.attribute == Attribute::StrokeWidth {
113	                    shape.stroke.width = v
114	                } else {
115	                    shape.stroke.dash_offset = v
116	                }
117	                *cs = true;
118	            }
119	            Attribute::D => return Err(diag(ErrorKind::Unsupported, t.element.offset)),
120	            Attribute::X
121	            | Attribute::Y
122	            | Attribute::Cx
123	            | Attribute::Cy
124	            | Attribute::Width
125	            | Attribute::Height
126	            | Attribute::Rx
127	            | Attribute::Ry
128	            | Attribute::R
129	                if item.value.kind == ValueKind::Number =>
130	            {
131	                if has_effect(view, i, control, work)? {
132	                    return Err(diag(ErrorKind::Unsupported, t.element.offset));
133	                }
134	                let delta = item.value.number[0] - t.base_value.number[0];
135	                if !delta.is_finite() || delta.abs() > 1e6 {
136	                    return Err(diag(ErrorKind::Unsupported, t.element.offset));
137	                }
138	                let mut local = affine_identity();
139	                match t.attribute {
140	                    Attribute::X | Attribute::Cx => local.e = delta,
141	                    Attribute::Y | Attribute::Cy => local.f = delta,
142	                    _ => {
143	                        let base = t.base_value.number[0];
144	                        if base <= 0. {
145	                            return Err(diag(ErrorKind::Unsupported, t.element.offset));
146	                        }
147	                        let scale = item.value.number[0] / base;
148	                        if !scale.is_finite() || scale < 0. || scale > 1e6 {
149	                            return Err(diag(ErrorKind::Unsupported, t.element.offset));
150	                        }
151	                        let inv = inverse(world[i], 1e-15)
152	                            .ok_or_else(|| diag(ErrorKind::Unsupported, t.element.offset))?;
153	                        let b = shape_bounds(shape, edges, inv, control, work)?;
154	                        if t.attribute == Attribute::Height || t.attribute == Attribute::Ry {
155	                            local.d = scale;
156	                            local.f = b[1] * (1. - scale);
157	                        } else {
158	                            let center = if t.attribute == Attribute::R {
159	                                (b[0] + b[2]) * 0.5
160	                            } else {
161	                                b[0]
162	                            };
163	                            local.a = scale;
164	                            local.e = center * (1. - scale);
165	                            if t.attribute == Attribute::R {
166	                                local.d = scale;
167	                                local.f = ((b[1] + b[3]) * 0.5) * (1. - scale);
168	                            }
169	                        }
170	                    }
171	                }
172	                if shape
173	                    .fill_paint
174	                    .is_some_and(|p| fills.get(p).is_some_and(|p| p.kind == PaintKind::Pattern))
175	                {
176	                    return Err(diag(ErrorKind::Unsupported, t.element.offset));
